<?php
namespace App\Services;
use App\Models\{InventoryLocation, InventoryMovement, SupplyBatch};
use Carbon\Carbon;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class InventoryService {
 public function receive(array $d,int $uid): InventoryMovement { return DB::transaction(function()use($d,$uid){ if(!empty($d['idempotency_key'])&&($old=InventoryMovement::where('idempotency_key',$d['idempotency_key'])->first()))return $old; $receivedOn=Carbon::parse($d['received_on']); if(!empty($d['expires_on'])&&Carbon::parse($d['expires_on'])->lt($receivedOn))throw ValidationException::withMessages(['expires_on'=>'The expiration date cannot be earlier than the receipt date.']); if(!InventoryLocation::whereKey($d['location_id'])->where('is_active',true)->lockForUpdate()->exists())throw ValidationException::withMessages(['location_id'=>'The selected inventory location is inactive.']); $b=SupplyBatch::lockForUpdate()->firstOrCreate(['supply_item_id'=>$d['supply_item_id'],'location_id'=>$d['location_id'],'batch_number'=>$d['batch_number']],['received_on'=>$d['received_on'],'expires_on'=>$d['expires_on']??null,'quantity_received'=>0,'quantity_available'=>0,'status'=>'available']);$q=(float)$d['quantity'];$b->increment('quantity_received',$q);$b->increment('quantity_available',$q);return InventoryMovement::create(['reference'=>'RCV-'.str()->upper(str()->random(16)),'supply_batch_id'=>$b->id,'user_id'=>$uid,'movement_type'=>'receipt','quantity'=>$q,'idempotency_key'=>$d['idempotency_key']??null,'notes'=>$d['notes']??null]); }); }
 public function release(array $d,int $uid): InventoryMovement { return DB::transaction(function()use($d,$uid){ if(!empty($d['idempotency_key'])&&($old=InventoryMovement::where('idempotency_key',$d['idempotency_key'])->first()))return $old;$b=SupplyBatch::lockForUpdate()->findOrFail($d['supply_batch_id']);if($b->expires_on&&$b->expires_on->isPast())throw ValidationException::withMessages(['supply_batch_id'=>'Expired batches cannot be released.']);$q=(float)$d['quantity'];if($q<=0||$b->quantity_available<$q)throw ValidationException::withMessages(['quantity'=>'Insufficient available stock.']);$b->decrement('quantity_available',$q);return InventoryMovement::create(['reference'=>'REL-'.str()->upper(str()->random(16)),'supply_batch_id'=>$b->id,'user_id'=>$uid,'movement_type'=>'release','quantity'=>$q,'idempotency_key'=>$d['idempotency_key']??null,'recipient'=>$d['recipient'],'purpose'=>$d['purpose'],'notes'=>$d['notes']??null]); }); }
 public function adjust(array $d,int $uid): InventoryMovement { return DB::transaction(function()use($d,$uid){$b=SupplyBatch::lockForUpdate()->findOrFail($d['supply_batch_id']);$q=(float)$d['quantity'];$new=(float)$b->quantity_available+$q;if($new<0)throw ValidationException::withMessages(['quantity'=>'Adjustment would create negative stock.']);$b->update(['quantity_available'=>$new]);return InventoryMovement::create(['reference'=>'ADJ-'.str()->upper(str()->random(16)),'supply_batch_id'=>$b->id,'user_id'=>$uid,'movement_type'=>'adjustment','quantity'=>$q,'adjustment_reason'=>$d['adjustment_reason'],'notes'=>$d['notes']??null]);}); }
}
